program_src = '''from collections import deque


def transform(grid):
    """Color cavities bounded by 1s with an inner 3 rim and outer 2 halo."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Label 4-connected zero regions. A region that does not touch the edge
    # is enclosed by the line drawing.
    zero_id = [[-1] * w for _ in range(h)]
    zero_regions = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or zero_id[r][c] != -1:
                continue
            idx = len(zero_regions)
            q = [(r, c)]
            zero_id[r][c] = idx
            cells = []
            touches_edge = False
            for x, y in q:
                cells.append((x, y))
                touches_edge |= x == 0 or y == 0 or x == h - 1 or y == w - 1
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if (0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 0
                            and zero_id[nx][ny] == -1):
                        zero_id[nx][ny] = idx
                        q.append((nx, ny))
            zero_regions.append((cells, touches_edge))

    enclosed_ids = {
        idx for idx, (_, touches_edge) in enumerate(zero_regions)
        if not touches_edge
    }

    # Mark the cavity's one-cell inner rim. Diagonal contact with the outline
    # counts when identifying this rim.
    active_ones = set()
    for idx in enclosed_ids:
        for r, c in zero_regions[idx][0]:
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1:
                        out[r][c] = 3
                        active_ones.add((nr, nc))

    # Group outline pixels by 8-connectivity. If a component bounds a cavity,
    # color its one-cell exterior halo 2. Keep the cavity side colored 3.
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            component = []
            for x, y in q:
                component.append((x, y))
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if dr == 0 and dc == 0:
                            continue
                        nx, ny = x + dr, y + dc
                        if (0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 1
                                and (nx, ny) not in seen):
                            seen.add((nx, ny))
                            q.append((nx, ny))
            if not any(point in active_ones for point in component):
                continue
            for x, y in component:
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if dr == 0 and dc == 0:
                            continue
                        nx, ny = x + dr, y + dc
                        if (0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 0
                                and zero_id[nx][ny] not in enclosed_ids):
                            out[nx][ny] = 2
    return out
